package org.eclipse.rdf4j.query.impl;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Arrays;
import java.util.List;
import java.util.Set;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.junit.jupiter.api.Test;

class BindingSetSnapshotsTest {

	@Test
	void undefSlotRemainsUnboundWhileItsNameRemainsPossible() {
		Value value = SimpleValueFactory.getInstance().createLiteral("value");
		ListBindingSet source = new ListBindingSet(List.of("undef", "bound"), Arrays.asList(null, value));

		BindingSet snapshot = BindingSetSnapshots.copyOf(source);

		assertEquals(Set.of("undef", "bound"), snapshot.getBindingNames());
		assertFalse(snapshot.hasBinding("undef"));
		assertNull(snapshot.getBinding("undef"));
		assertNull(snapshot.getValue("undef"));
		assertTrue(snapshot.hasBinding("bound"));
		assertEquals(value, snapshot.getValue("bound"));
		assertEquals(1, snapshot.size());
	}
}
